    def start_5g_uplink_ccm_test_pusch(self, dist_name, interval, beam_pattern_id,
                                       frc_index, prb_offset, digital_out_type,
                                       digital_out_rate, ul_dmrs_mapping_type, is_ptrs_fr2_enabled,
                                       ru_mode, phys_cell_id,
                                       bb_selector=None, nrarfcn_ul=None, nrarfcn_dl=None, num_uci_bits=None,
                                       csi_payload_bit=None, timeout=60, **kwargs):
        """
        Starts 5G `Pusch` Performance CCM Test (start5GUplinkCCMTest).

        :param str dist_name: `NRCELL_R` object to perform the test on.
        :param float interval: Reporting time interval [0.1 .. 3600] (with step 0.1).
        :param list[int] beam_pattern_id: [0..1200].
        :param str frc_index: One of the following: 'G_FR1_A3_8', 'G_FR1_A3_9', 'G_FR1_A3_10',
                                                    'G_FR1_A3_12', 'G_FR1_A3_13', 'G_FR1_A3_14',
                                                    'G_FR1_A3_22', 'G_FR1_A3_23', 'G_FR1_A3_24',
                                                    'G_FR1_A3_26', 'G_FR1_A3_27', 'G_FR1_A3_28',
                                                    'G_FR1_A4_8', 'G_FR1_A4_9', 'G_FR1_A4_10',
                                                    'G_FR1_A4_12', 'G_FR1_A4_13', 'G_FR1_A4_14',
                                                    'G_FR1_A4_22', 'G_FR1_A4_23', 'G_FR1_A4_24',
                                                    'G_FR1_A4_26', 'G_FR1_A4_27', 'G_FR1_A4_28',
                                                    'G_FR1_A5_8', 'G_FR1_A5_9', 'G_FR1_A5_10',
                                                    'G_FR1_A5_12', 'G_FR1_A5_13', 'G_FR1_A5_14',
                                                    'G_FR2_A3_4', 'G_FR2_A3_9', 'G_FR2_A3_16',
                                                    'G_FR2_A3_21', 'G_FR2_A4_4', 'G_FR2_A4_9',
                                                    'G_FR2_A4_14', 'G_FR2_A4_19', 'G_FR2_A5_4',
                                                    'G_FR2_A5_9', 'G-FR1-A1-2', 'G-FR1-A1-5',
                                                    'G-FR1-A2-5', 'G-FR1-A1-1', 'G-FR1-A1-4',
                                                    'G-FR1-A2-4', 'G_FR1_A3_31', 'G_FR1_A3_32'
        :param int prb_offset: [0..273].
        :param str digital_out_type: Either `SerialKeysight` or `SerialRs`.
        :param str digital_out_rate: Either `Bitrate_115dot2K`,
                                     `Bitrate_1dot92M` or `Bitrate_460dot8K`.
        :param str ul_dmrs_mapping_type: "A" or "B".
        :param bool is_ptrs_fr2_enabled.
        :param str ru_mode: One of the following:
                            `NR_Only`, `MSR` (`MSR` is supported when RU contains EUTRA.Frequency.Band)
        :param int phys_cell_id: [0..1007].
        :param int bb_selector: (Optional) [0..3].
        :param int nrarfcn_ul: (Optional) [0..3279165].
        :param int nrarfcn_dl: (Optional) [0..3279165].
        :param int num_uci_bits: (Optional) [0.255].
        :param list[int] csi_payload_bit: (Optional, two items at most) list of integers [0..4294967295]
        :param int timeout: (optional) Timeout for the operation.

        :return: It returns dict with data.

        Example response

        ::
            {
                "indicationDistName": "/MRBTS-1/RAT-1/URI-1/SESSION-13/START_NR_UPLINKCCM_TEST_IND-0",
                "confirmationNode": {
                    "distName": "/MRBTS-1/RAT-1/URI-1/SESSION-13/START_NR_UPLINKCCM_TEST_IND-0/ACK-1",
                    "parameters": {}
                },
                "resultNode": {
                    "distName": "/MRBTS-1/RAT-1/URI-1/SESSION-13/START_NR_UPLINKCCM_TEST_IND-0/NR_TEST_RESULT-1",
                    "parameters": {
                        "status": "Succeeded"
                    }
                }
            }

        More details:
        https://onion.wroclaw.nsn-rdnet.net/branches/master/cli-docs/tutorial-start5GUplinkCCMTest.html

        """
        if not isinstance(is_ptrs_fr2_enabled, bool):
            raise ValueError('Parameter is_ptrs_fr2_enabled should be bool True or False not {}'
                             .format(type(is_ptrs_fr2_enabled)))

        nrarfcn_dl = int(nrarfcn_dl) if nrarfcn_dl is not None else None

        if not isinstance(beam_pattern_id, list):
            raise TypeError('Parameter beam_pattern_id should be list type not {}'
                            .format(type(beam_pattern_id)))

        beam_pattern_id = [int(element) for element in beam_pattern_id]

        interval = float(interval)

        num_uci_bits = int(num_uci_bits) if num_uci_bits is not None else None
        if csi_payload_bit:
            try:
                csi_payload_bit = [int(element) for element in csi_payload_bit]
            except ValueError:
                msg = 'Parameter csi_payload_bit should be list type not {}'.format(type(csi_payload_bit))
                raise TypeError(msg)

        PERFORMANCE_TEST_TYPE = "Pusch"
        pusch_schema = CCMUplinkPusch(nrcell_rdn=dist_name, nrarfcn_ul=nrarfcn_ul, reporting_time_interval=interval,
                                      beam_pattern_id=beam_pattern_id, performance_test_type=PERFORMANCE_TEST_TYPE,
                                      frc_index=frc_index, prb_offset=prb_offset, digital_out_type=digital_out_type,
                                      digital_out_rate=digital_out_rate, ul_dmrs_mapping_type=ul_dmrs_mapping_type,
                                      is_ptrs_fr2_enabled=is_ptrs_fr2_enabled, ru_mode=ru_mode,
                                      phys_cell_id=phys_cell_id, bb_selector=bb_selector, nrarfcn_dl=nrarfcn_dl,
                                      num_uci_bits=num_uci_bits, csi_payload_bit=csi_payload_bit)
        parameters = pusch_schema.as_dict()

        return self._api_client.execute_procedure('start5GUplinkCCMTest',
                                                  parameters, timeout)

    def start_5g_uplink_test(self, dist_name, frc_index, beam_pattern_id,
                             interval, prb_offset, ru_mode, phys_cell_id,
                             nrarfcn_ul=None, nrarfcn_dl=None, timeout=60):
        """
        Starts 5G Uplink Test.

        :param str dist_name: `NRCELL_R` object to perform the test on.
        :param str frc_index: One of the following: `G_FR1_A1_1`, `G_FR1_A1_2`,
                                `G_FR1_A1_4`, `G_FR1_A1_5`, `G_FR1_A1_7`, `G_FR1_A2_1`,
                                `G_FR1_A2_4`, `G_FR1_A2_5`, `GFR2_A1_2`, `G_FR2_A1_3`.
        :param list[int] beam_pattern_id: [0..1200].
        :param float interval: Reporting time interval [1..3600].
        :param int prb_offset: [0..273]
        :param str ru_mode: One of the following:
                            `NR_Only`, `MSR` (`MSR` is supported when RU contains EUTRA.Frequency.Band)
        :param int phys_cell_id: [0..1007].
        :param int nrarfcn_ul: (Optional) [0..3279165]
        :param int nrarfcn_dl: (Optional) [0..3279165]
        :param Union[int,str] timeout: (optional) Timeout for the operation.
        :return: It returns dict with data.

        Example response

        ::

            {
              "indicationDistName": "/MRBTS-1/RAT-1/URI-1/SESSION-13/START_NR_UPLINK_TEST_IND-0",
              "confirmationNode": {
                 "distName": "/MRBTS-1/RAT-1/URI-1/SESSION-13/START_NR_UPLINK_TEST_IND-0/ACK-1",
                 "parameters": {}
              },
              "resultNode": {
                 "distName": "/MRBTS-1/RAT-1/URI-1/SESSION-13/START_NR_UPLINK_TEST_IND-0/NR_TEST_RESULT-1",
                 "parameters": {
                    "status": "Succeeded"
                 }
                }
            },

        More details:
        https://onion.wroclaw.nsn-rdnet.net/branches/master/cli-docs/tutorial-start5GUplinkTest.html

        """
        if not isinstance(beam_pattern_id, list):
            raise TypeError('Parameter beam_pattern_id should be list type not {}'
                            .format(type(beam_pattern_id)))

        beam_pattern_id = [int(element) for element in beam_pattern_id]

        interval = float(interval)

        nrarfcn_dl = int(nrarfcn_dl) if nrarfcn_dl is not None else None

        params_to_check = {'frc_index': frc_index, 'beam_pattern_id': beam_pattern_id, 'interval': interval,
                           'prb_offset': prb_offset, 'ru_mode': ru_mode, 'phys_cell_id': phys_cell_id,
                           'nrarfcn_ul': nrarfcn_ul, 'nrarfcn_dl': nrarfcn_dl}

        self._validation_5g_uplink_parameters(params_to_check)

        parameters = {
            'nrcell_rDN': dist_name,
            'params': {
                'frcIndex': frc_index,
                'beamPatternId': beam_pattern_id,
                'reportingTimeInterval': interval,
                'prbOffset': prb_offset,
                'ruMode': ru_mode,
                'physCellId': phys_cell_id,
                'nrarfcnUl': nrarfcn_ul,
                'nrarfcnDl': nrarfcn_dl
            }
        }
        parameters['params'] = {k: v for k, v in parameters['params'].items() if v is not None}

        return self._api_client.execute_procedure('start5GUplinkTest',
                                                  parameters, timeout)

    def _validation_5g_uplink_parameters(self, params):
        frc_index = (params['frc_index'] in ("G_FR1_A1_1", "G_FR1_A1_2", "G_FR1_A1_4",
                                             "G_FR1_A1_5", "G_FR1_A1_7", "G_FR1_A2_1",
                                             "G_FR1_A2_4", "G_FR1_A2_5", "GFR2_A1_2",
                                             "G_FR2_A1_3"))
        beam_pattern_id = (all(0 <= item <= 1200 for item in params['beam_pattern_id']))
        interval = (1 <= params['interval'] <= 3600)
        prb_offset = (0 <= params['prb_offset'] <= 273)
        ru_mode = (params['ru_mode'] in ("NR_Only", "MSR"))
        phys_cell_id = (0 <= params['phys_cell_id'] <= 1007)
        nrarfcn_ul = (params['nrarfcn_ul'] is None or (0 <= params['nrarfcn_ul'] <= 3279165))
        nrarfcn_dl = (params['nrarfcn_dl'] is None or (0 <= params['nrarfcn_dl'] <= 3279165))
        params_to_check = {'frc_index': frc_index, 'beam_pattern_id': beam_pattern_id, 'interval': interval,
                           'prb_offset': prb_offset, 'ru_mode': ru_mode, 'phys_cell_id': phys_cell_id,
                           'nrarfcn_ul': nrarfcn_ul, 'nrarfcn_dl': nrarfcn_dl}

        self._check_parameters(params_to_check, params, "tutorial-start5GUplinkTest.html")

    def change_beam_pattern_id(self, test_dn, beam_pattern_id, timeout=10):
        """

        :param str test_dn:  DistName of target test
        :param list[int] beam_pattern_id:  Id of beam pattern <0 to 1200> (two items at most)
        :param Union[int,str] timeout: (optional) Timeout for the operation, defaults to 10
        :param AdminConnection connection: AdminConnection object or if used, string name alias.
        :return str: status "Rejected", "Failed" or "Succeeded"

        More details:
        https://onion.wroclaw.nsn-rdnet.net/branches/master/cli-docs/tutorial-changeBeamPatternId.html

        """
        if not isinstance(beam_pattern_id, list):
            raise TypeError('Parameter beam_pattern_id should be list type not {}'
                            .format(type(beam_pattern_id)))

        beam_pattern_id = [int(element) for element in beam_pattern_id]

        parameters = {
            "testDN": test_dn,
            "beamPatternId": beam_pattern_id
        }
        return self._api_client.execute_procedure('changeBeamPatternId', parameters=parameters, timeout=timeout)
